const logClose=document.getElementById('logClose'),veil=document.getElementById('drawerVeil');function closeHistory(){closeLogDrawer();header.querySelector('[data-live="history"]').focus();}if(logClose)logClose.onclick=closeHistory;if(veil)veil.onclick=closeHistory;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('drawer'))closeHistory();});
