const searchQueries=new Map();
function composeTools(scene){const tab=XTSandbox.view.tab,sub=XTSandbox.view.sub,key=tab+'|'+sub;if(!['bag'].includes(tab)&&!(tab==='home'&&sub==='staff')&&!(tab==='self'&&sub==='relations'))return;const list=scene.querySelector('.sb-scroll');if(!list?.parentNode)return;const rows=[...list.querySelectorAll('.sb-item,.sb-person')];if(!rows.length)return;const tools=document.createElement('label');tools.className='next-search';tools.innerHTML='<span>⌕</span><input type="search" placeholder="按名称查找" aria-label="查找当前列表">';const input=tools.querySelector('input');input.value=searchQueries.get(key)||'';function filter(){searchQueries.set(key,input.value);const q=input.value.trim().toLowerCase();for(const row of rows)row.hidden=!!q&&!row.textContent.toLowerCase().includes(q);}input.addEventListener('input',filter);list.prepend(tools);filter();}
