function composeBattle(scene){const b=G?.qi51?.battle,scroll=scene.querySelector('.sb-scroll');if(!b||!scroll?.parentNode)return;const meter=(name,hp,max,mp)=>`<section><span class="live-eyebrow">${mp?'此身':'对手'}</span><h3>${esc(name)}</h3><div class="next-vital"><span>气血 ${hp} / ${max}</span><div><i style="width:${Math.max(0,Math.min(100,hp/max*100))}%"></i></div></div>${mp?'<small>真元 '+esc(mp)+'</small>':''}</section>`;const hero=document.createElement('div');hero.className='next-battle';hero.innerHTML=meter(G.name,b.hp,b.stats.maxHp,Number(b.mp.toFixed(1))+' / '+b.stats.maxMp)+'<span class="next-battle-seal">第<br>'+String(b.turn+1)+'<br>回</span>'+meter(b.enemy.name,b.enemy.hp,b.enemy.maxHp,null);const card=scroll.querySelector('.sb-card'),p=card?.querySelector('p');if(p){let removed=0;for(const node of [...p.childNodes]){const line=node.nodeName==='BR';node.remove();if(line&&++removed===2)break;}}const actions=card?.querySelector('.sb-buttons');if(actions){actions.classList.add('next-battle-actions');actions.querySelector('button')?.classList.add('on');}scroll.prepend(hero);}
function composeAuction(scene){for(const lot of scene.querySelectorAll('.auction-lot43')){const heading=lot.querySelector('h3');if(!heading)continue;const banner=document.createElement('header');banner.className='next-auction-item';banner.innerHTML='<span class="next-lot-mark" aria-hidden="true">拍</span>';const text=document.createElement('div');const number=lot.querySelector('small');if(number)text.append(number);text.append(heading);const bid=lot.querySelector('strong');if(bid)text.append(bid);banner.append(text);lot.prepend(banner);lot.querySelector('[data-sb="a43:bid"],[data-sb="a44:bid"]')?.classList.add('on');}}
