 const guide=[...scene.querySelectorAll(':scope>.sb-card')].find(n=>n.querySelector('h4')?.textContent==='炼气行程');if(guide){const parent=guide.parentNode,next=guide.nextSibling,fold=noteFold(guide,'当前修行目标与传习入口');fold.classList.add('next-cult-guide');parent.insertBefore(fold,next);}
 for(const person of scene.querySelectorAll('.sb-person')){if(!person.querySelector('.next-person-mark')){const mark=document.createElement('span');mark.className='next-person-mark';mark.setAttribute('aria-hidden','true');mark.innerHTML='<svg viewBox="0 0 58 65" aria-hidden="true"><path d="M6 65c1-14 9-24 23-24s22 10 23 24" fill="#7e8f79"/><path d="M22 34v10l7 9 7-9V34" fill="#b8baa0"/><ellipse cx="29" cy="24" rx="11" ry="15" fill="#c6c3a5"/><path d="M17 25c-4-20 22-29 25-8l-4 10-4-12-17 10z" fill="#627b68"/><path d="M13 65l9-21 7 13 7-13 9 21" fill="#d1d2ba"/><path d="M29 57v8" stroke="#87977e"/></svg>';person.prepend(mark);}}
 for(const card of scene.querySelectorAll('.sb-card'))card.classList.add('next-section');
