function present(){const current=stage();document.body.dataset.uiStage=current;document.body.classList.toggle('live-game',current==='play');document.body.classList.toggle('live-opening',current!=='play'&&current!=='title');document.body.classList.toggle('live-creating',current==='create');document.getElementById('live-context').textContent=G?[placeName(G.place),current==='play'?labels[groupFor(XTSandbox.view.tab)]||'':'此生长卷'].filter(Boolean).join(' / '):'凡界篇 · 山河长卷';if(!G)decorateStart();else if(current!=='play')decorateChapter(current);else decoratePlay();const key=current==='play'?null:[current,G?.world36?.playerId||'',G?.opening46?.step||0,G?.opening46?.childhood?.step||0,G?.curEvent?.id||'',G?.lastResult?.title||''].join('|');if(key&&key!==lastChapter&&document.scrollingElement){document.scrollingElement.scrollTop=0;document.getElementById('scene').scrollTop=0;}lastChapter=key;}
